'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isFloat16Array = require( '@stdlib/assert/is-float16array' );
var uniform = require( '@stdlib/random/array/uniform' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Float16Array = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function.
*
* @private
* @param {number} a - first numeric value for comparison
* @param {number} b - second numeric value for comparison
* @returns {number} comparison result
*/
function compare( a, b ) {
	if ( a > b ) {
		return 1;
	}
	if ( a < b ) {
		return -1;
	}
	return 0;
}


// MAIN //

bench( format( '%s:toSorted', pkg ), function benchmark( b ) {
	var out;
	var arr;
	var i;

	arr = new Float16Array( uniform( 10, 0.0, 10.0 ) );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.toSorted( compare );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isFloat16Array( out ) ) {
		b.fail( 'should return a Float16Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
